process.loadEnvFile('/Users/mrnetwork/Bulwark/.claude/worktrees/agent-aaf61e14ffc6e32d9/.env');
const h = { authorization: `Bearer ${process.env.CRUSTDATA_API_KEY}`, 'content-type': 'application/json', 'x-api-version': '2025-11-01' };
const b = await fetch('https://api.crustdata.com/account/credits', { headers: h });
console.log('credits', b.status, await b.text());
const qs = [
  ['taxonomy.categories', 'Artificial Intelligence'],
  ['taxonomy.categories', 'Generative'],
  ['taxonomy.professional_network_specialities', 'AI Agents'],
  ['taxonomy.professional_network_specialities', 'Agentic'],
  ['taxonomy.professional_network_specialities', 'LLM'],
  ['taxonomy.professional_network_specialities', 'Large Language'],
  ['taxonomy.professional_network_specialities', 'Conversational AI'],
  ['taxonomy.professional_network_specialities', 'AI Customer'],
];
for (const [field, query] of qs) {
  const r = await fetch('https://api.crustdata.com/company/search/autocomplete', { method: 'POST', headers: h, body: JSON.stringify({ field, query, limit: 8 }) });
  const t = await r.text();
  console.log(field, JSON.stringify(query), r.status, 'credits:', r.headers.get('x-credits-used'), t.slice(0, 600));
}

